#!/usr/bin/env python3
"""
Round 112c (tiles), 29 September 2026. scripts/capture.py (fixes from the
first run, plus round 111c's sources), capture_ipn.py (certificate fix) and
the new capture_stb.py. Whole files, each written only if it differs.
"""
import base64, pathlib

FILES = {'scripts/capture.py': '', 'scripts/capture_ipn.py': '', 'scripts/capture_stb.py': ''}


def main():
    for p, b in FILES.items():
        data = base64.b64decode(b)
        f = pathlib.Path(p)
        if f.exists() and f.read_bytes() == data:
            print(f"round112c: {p} already up to date")
            continue
        f.parent.mkdir(parents=True, exist_ok=True)
        f.write_bytes(data)
        print(f"round112c: wrote {p}")


if __name__ == "__main__":
    main()
